<?php
require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php'; zorunlu_rol('admin');
$ligId=(int)($_GET['lig_id']??$_POST['lig_id']??0);$st=$pdo->prepare("SELECT * FROM ligler WHERE id=? AND tur='bireysel'");$st->execute([$ligId]);$lig=$st->fetch();if(!$lig){flash_set('hata','Bireysel lig bulunamadı.');redirect(BASE_URL.'/admin/ligler.php');}
$gruplar=$pdo->prepare('SELECT * FROM gruplar WHERE lig_id=? ORDER BY grup_adi');$gruplar->execute([$ligId]);$gruplar=$gruplar->fetchAll();$grupId=(int)($_GET['grup_id']??$_POST['grup_id']??($gruplar[0]['id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['csrf']??'')){flash_set('hata','Güvenlik doğrulaması başarısız.');}else{$pdo->prepare('DELETE FROM bireysel_lig_kayitlari WHERE lig_id=? AND grup_id=?')->execute([$ligId,$grupId]);$ins=$pdo->prepare('INSERT INTO bireysel_lig_kayitlari(lig_id,grup_id,sporcu_id) VALUES(?,?,?)');foreach($_POST['sporcular']??[] as $sid)$ins->execute([$ligId,$grupId,(int)$sid]);flash_set('basari','Sporcu kayıtları güncellendi.');}redirect(BASE_URL.'/admin/bireysel-katilim.php?lig_id='.$ligId.'&grup_id='.$grupId);}
$sporcular=$pdo->query('SELECT s.id,s.ad,s.soyad,t.takim_adi FROM sporcular s LEFT JOIN takimlar t ON t.id=s.takim_id ORDER BY s.ad,s.soyad')->fetchAll();$sec=$pdo->prepare('SELECT sporcu_id FROM bireysel_lig_kayitlari WHERE lig_id=? AND grup_id=?');$sec->execute([$ligId,$grupId]);$sec=array_flip(array_column($sec->fetchAll(),'sporcu_id'));ob_start();?>
<div class="toolbar"><a class="btn" href="<?= BASE_URL ?>/admin/ligler.php">← Liglere dön</a></div><div class="card"><div class="card-head"><h2><?= e($lig['lig_adi']) ?> — sporcu kayıtları</h2></div><form method="get" class="toolbar"><input type="hidden" name="lig_id" value="<?= $ligId ?>"><select name="grup_id" onchange="this.form.submit()"><?php foreach($gruplar as $g):?><option value="<?= (int)$g['id'] ?>" <?= $grupId===(int)$g['id']?'selected':'' ?>><?= e($g['grup_adi']) ?></option><?php endforeach;?></select></form><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="lig_id" value="<?= $ligId ?>"><input type="hidden" name="grup_id" value="<?= $grupId ?>"><p class="muted">Bu grupta bireysel yarışacak sporcuları seçin.</p><div class="katilim-listesi"><?php foreach($sporcular as $s):?><label class="katilim-satir"><input type="checkbox" name="sporcular[]" value="<?= (int)$s['id'] ?>" <?= isset($sec[$s['id']])?'checked':'' ?>><span><?= e($s['ad'].' '.$s['soyad']) ?></span><small><?= e($s['takim_adi']?:'Takımsız') ?></small></label><?php endforeach;?></div><div class="form-actions"><button class="btn btn-primary">Kayıtları kaydet</button></div></form></div>
